def Fh(x,Em=WE,Pm=WP,m0=M0,vo0=VO0,m1=M1,vo1=VO1,wu=WU,hard=(True,True)):
    B=len(x); h=Em[x]+Pm[None,:,:]
    for (m,vo,hd) in ((m0,vo0,hard[0]),(m1,vo1,hard[1])):
        s=np.einsum('bid,bjd->bij',h@m,h)
        if hd:
            a=np.zeros_like(s); a[np.arange(B)[:,None],np.arange(4)[None,:],s.argmax(-1)]=1.0
        else:
            a=np.exp(s-s.max(-1,keepdims=True)); a/=a.sum(-1,keepdims=True)
        h=h+np.einsum('bij,bjd->bid',a,h@vo)
    return h[:,3]@wu
