import numpy as np
def build(WE,WP,m0,vo0,m1,vo1,wu,poszero,mode):
    E0=WE+WP[3]; P0=WP-WP[3]
    c=P0[poszero].copy(); P1=P0-c; E1=E0+c
    if mode=='E': S=np.linalg.inv(E1[1:4])
    elif mode=='P': S=np.linalg.inv(P1[1:4])
    elif mode=='PE': S=np.linalg.inv((P1+E1)[1:4])
    else: S=np.eye(3)
    iS=np.linalg.inv(S)
    return [E1@S,(P1@S)[1:4],iS@m0@iS.T,iS@vo0@S,iS@m1@iS.T,iS@vo1@S,iS@wu]
def cost(mats):
    tot=0; cnt=0; mx=0
    for M in mats:
        A=np.array(M)
        for v in A.ravel():
            s='%.4g'%v
            if abs(v)<1e-12: s='0'
            tot+=len(s); cnt+=1; mx=max(mx,abs(v))
        tot+=4  # brackets/commas approx
    return tot,cnt,round(mx,1)
