DESCRIPTION="Attention-only transformer, written in a basis where the token embeddings of tokens 1,2,3 are the coordinate axes (token 0 is a free vector t). Residual = token code + position vector P (position 3 = 0). Each layer: bilinear score h_i M h_j, softmax over keys, add the attention-weighted values h V. Layer 1's score matrix is exactly rank 2 (third row = ab times the first two). Readout: last position x U (class 1 dropped as the reference class)."
t={mk(t)}
P={mk(Pg)}
M0={mk(M0g)}
V0={mk(V0g)}
R={mk(R)}
ab={mk(ab)}
V1={mk(V1g)}
U={mk(Ug)}
def model(x, iv):
    B = x.shape[0]
    h = iv('e', (np.vstack([t, np.eye(3)])[x] + P).reshape(B, -1)).reshape(B, 4, 3)
    for l, (m, v) in enumerate(((M0, V0), (np.vstack([R, ab @ R]), V1))):
        s = h @ m @ h.transpose(0, 2, 1)
        a = np.exp(s - s.max(-1, keepdims=True)); a = a / a.sum(-1, keepdims=True)
        a = iv('p%d' % l, a.reshape(B, -1)).reshape(B, 4, 4)
        o = iv('o%d' % l, (a @ (h @ v)).reshape(B, -1)).reshape(B, 4, 3)
        h = iv('r%d' % l, (h + o).reshape(B, -1)).reshape(B, 4, 3)
    return np.insert(h[:, 3] @ U, 1, 0, 1)
